import{_ as e,o as t,c as o,a4 as r}from"./chunks/framework.CmuCl-jw.js";const g=JSON.parse('{"title":"Arcsecond.local","description":"","frontmatter":{},"headers":[],"relativePath":"local/index.md","filePath":"local/index.md"}'),s={name:"local/index.md"};function n(i,a,l,c,d,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="arcsecond-local" tabindex="-1">Arcsecond.local <a class="header-anchor" href="#arcsecond-local" aria-label="Permalink to “Arcsecond.local”">​</a></h1><p><strong>Arcsecond.local is the full Arcsecond platform, self-hosted on your own infrastructure.</strong> It is the off-the-shelf, multi-user and multi-telescope, industry-grade platform dedicated to astronomical observatories — the whole system, running on your machines, under your control, with your data never leaving them.</p><p>Everything lives in <a href="/apps/">four apps</a>:</p><ul><li><strong><a href="/apps/night-studio/">Night Studio</a></strong> — prepare your observations.</li><li><strong><a href="/apps/control-room/">Control Room</a></strong> — acquire new data and automate your nights.</li><li><strong><a href="/apps/data/">Data Grand Central</a></strong> — store, package and share your data.</li><li><strong><a href="/apps/headquarters/">Observatory Headquarters</a></strong> — every install is <strong>multi-user by design</strong>, so running your observatory as a team comes built in.</li></ul><p>Contact us at <a href="mailto:team@arcsecond.io" target="_blank" rel="noreferrer">team@arcsecond.io</a> to learn more about Arcsecond.local and how to get started.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><p>A quick guide to getting up and running:</p><ol><li><a href="./installation">Installation</a>: simple steps to install and run Arcsecond.local.</li><li><a href="./updates">Updates</a>: keep your installation up to date.</li><li><strong>Configuration</strong>: set up member accounts, observing sites and data storage for your observatory&#39;s needs.</li><li><strong>First Observations</strong>: run your nights with the <a href="/apps/control-room/">Control Room</a>. [IN PREP]</li><li><strong>Data Management</strong>: store and manage your data with <a href="/apps/data/">Data Grand Central</a>.</li></ol><p><a href="./troubleshooting">Troubleshooting</a>.</p><h2 id="self-hosting-guides" tabindex="-1">Self-Hosting Guides <a class="header-anchor" href="#self-hosting-guides" aria-label="Permalink to “Self-Hosting Guides”">​</a></h2><p>Operating Arcsecond.local is done through the <code>arcsecond</code> command-line tool (see the <a href="/cli/">CLI documentation</a>). The following guides cover the most common self-hosting tasks:</p><ul><li><a href="./alpaca-lan">Alpaca Server on the LAN</a>: connect Arcsecond.local to an Alpaca server running on another Windows machine.</li><li><a href="./webcam">Live-Image Proxy</a>: stream USB webcams, all-sky cameras and network cameras into Arcsecond.local.</li><li><a href="./backups">Backups</a>: where the Postgres dumps live, and how to list, inspect, and restore them.</li><li><a href="./rotate-postgres-password">Rotate Postgres Password</a>: rotate the database password on an existing install.</li><li><a href="./transient-alerts">Transient Alerts</a>: how to setup transient alert service</li></ul>',12)])])}const p=e(s,[["render",n]]);export{g as __pageData,p as default};
